'Units_Guide_Base' => 'Негізгі бірлік: «Негізгі бірлік» өрісін бос қалдырыңыз. Қор әрқашан осы бірлікпен есептеледі, мысалы, Дана.',
'Units_Guide_Sub' => 'Қосалқы бірлік: «Негізгі бірлікті» таңдап, оны сол негізгі бірлікке түрлендіру үшін «Оператор» мен «Операция мәнін» пайдаланыңыз.',
'Units_Guide_Example_Multiply' => 'Мысал: негізгі бірлігі Дана, операторы * және мәні 12 болатын Қорап. 1 Қорап сату қордан 12 Дананы алады.',
'Units_Guide_Example_Divide' => 'Мысал: негізгі бірлігі Килограмм, операторы / және мәні 1000 болатын Грамм. 500 Грамм сату қордан 0.5 Килограммды алады.',
'Units_Guide_Note' => '«Негізгі бірлік» ретінде тек негізгі бірліктерді таңдауға болады, ал қосалқы бірліктер пайдаланып тұрған бірлікті жоюға болмайды.',

'Amount_Paid' => 'Төленген сома',
'Payment_Amounts_Help' => 'Төленген сома қалдықты өтейді және қарызды азайтады. Алынған сома — берілген қолма-қол ақша: ол тек қайтарылатын қайтарымды есептеу үшін пайдаланылады және қарызды өзгертпейді.',

'Show_Tax_Desc' => 'Тапсырысты рәсімдеу кезінде бүкіл сатуға қолданылатын салық, жиындарда жеке «Тапсырыс салығы» жолы ретінде басылады.',
'Show_Items_Tax_Desc' => 'Әр тауардың өз салығының сомасы, «Тауарлар салығының жиыны» жолы ретінде басылады. Қосылған кезде аралық сома осы салықтарсыз көрсетіледі.',
'Show_Discount_Desc' => 'Бүкіл сатуға қолданылатын жеңілдік (кез келген ұпай жеңілдігін қоса), жиындарда жеке жол ретінде басылады.',
'Show_Product_Discount_Desc' => 'Әр тауардың өз жеңілдігі, тауарлар тізімінде сол тауардың астында басылады.',

