'Warehouses_Tab_Help' => 'Қоймаларыңызды (дүкендер/филиалдар) басқарыңыз. Әр қойманың өз қоры бар, ал әрбір құжат — сатулар, сатып алулар, тасымалдар, түзетулер — солардың біріне тіркеледі.',
'Warehouse_Locations_Tab_Help' => 'Әр қойманың ішіндегі сөре / төсеме орындарын анықтаңыз (мысалы, 2-өтпе – B сөресі). Тауарлардың физикалық сақталатын жерін көрсету үшін оларды тауарларға тағайындаңыз.',
