'Enable_Pos_Salesperson_Switch_Hint' => 'Сатуды жүйеден шықпай басқа қызметкерге тіркеу үшін POS экранында сатушыны таңдағышты көрсету. Таңдалған сатушы шот-фактурада сақталады және сату есептерінде пайдаланылады; белсенді POS сессиясы өзгермейді.',

