'QZ_Tray_Printer' => 'QZ Tray (осы компьютердегі принтер)',
'QZ_Printer_Name_Hint' => 'QZ Tray іске қосылған компьютерде көрсетілетін принтер атауы. Сол компьютердің әдепкі принтерін пайдалану үшін бос қалдырыңыз. Принтерлерді анықтау үшін ⟳ басыңыз.',
'QZ_Not_Running' => 'Бұл компьютерде QZ Tray іске қосылмаған. Оны qz.io сайтынан орнатып, іске қосулы ұстаңыз, содан кейін QZ сұрағанда осы веб-сайтқа рұқсат беріңіз.',
'Detect_Printers' => 'Принтерлерді анықтау',
'QZ_Download_Cert' => 'Сертификатты жүктеу (override.crt)',
'QZ_Setup_Title' => 'QZ Tray арқылы басып шығаруды қалай баптау керек (бір рет, жапсырма басатын әр компьютерде)',
'QZ_Step_Install' => '1. Бұл компьютерге QZ Tray орнатыңыз — оны qz.io сайтынан тегін жүктеп алыңыз, содан кейін іске қосып, жұмыс істеп тұрған күйде қалдырыңыз (ол Windows-та жүйелік науада немесе macOS-та мәзір жолағында тұрады).',
'QZ_Step_Connect' => '2. Жапсырма принтерін USB арқылы қосып, оның операциялық жүйеде орнатылғанын тексеріңіз (Windows: Параметрлер > Принтерлер мен сканерлер — macOS: Жүйе параметрлері > Принтерлер мен сканерлер).',
'QZ_Step_Detect' => '3. Осы компьютердегі принтерлерді анықтау үшін жоғарыдағы «Принтер атауы» жанындағы ⟳ батырмасын басып, жапсырма принтеріңізді таңдаңыз. Компьютердің әдепкі принтерін пайдалану үшін өрісті бос қалдырыңыз.',
'QZ_Step_Cert' => '4. Рұқсат терезесінсіз басып шығару үшін төмендегі сертификатты жүктеп алып, оны override.crt деп қайта атап, QZ Tray орнату қалтасына көшіріңіз (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Содан кейін QZ Tray-ден шығып, оны қайта іске қосыңыз.',
'QZ_Step_Test' => '5. Төмендегі «Тестілік жапсырманы басып шығару» батырмасын басыңыз. QZ Tray рұқсат сұраса, Рұқсат беру батырмасын басыңыз — сертификат орнатылғанда ол қайта сұрамайды.',
'QZ_Step_Save' => '6. Осы баптауларды сақтау үшін Жіберу батырмасын басыңыз. Штрихкодты басып шығару бетіндегі жапсырмалар енді осы принтерде браузердің басып шығару терезесінсіз тікелей басылады.',
'QZ_Setup_Note' => 'QZ Tray сіз шолу жасап отырған компьютерде жұмыс істейді, сондықтан Stocky қашықтағы серверде орналасса да бұл жұмыс істейді. Жапсырма басатын әр компьютерге QZ Tray орнатылуы керек.',

// PWA settings tab — installable app identity
'PWA_Enabled' => 'Орнатылатын қолданбаны қосу',
'PWA_Enabled_Help' => 'Браузерлерге бұл қолданбаны телефондарға, планшеттерге және компьютерлерге орнатуды ұсынуға мүмкіндік береді және офлайн беттерді кэште сақтайды. Мұны өшіру орнату ұсынысын барлық жерден алып тастайды және келесі кіргенде кэшті тазалайды.',
'PWA_Identity' => 'Қолданба сәйкестігі',
'PWA_Launch' => 'Іске қосу және сыртқы түр',
'PWA_App_Name' => 'Қолданба атауы',
'PWA_App_Name_Help' => 'Орнату ұсынысында және қолданбалар тізімінде көрсетіледі. Сыртқы түр баптауларындағы қолданба атауын пайдалану үшін бос қалдырыңыз.',
'PWA_Short_Name' => 'Қысқа атауы',
'PWA_Short_Name_Help' => 'Басты экрандарда белгішенің астында көрсетіледі, онда ұзын атаулар қиылады. Қолданба атауының "|" алдындағы бөлігін пайдалану үшін бос қалдырыңыз.',
