'PWA_Reinstall_Notice' => 'Қолданбаны бұрын орнатқан құрылғылар оны жойып, қайта орнатқанша ескі атау мен белгішені сақтайды.',

'Label_Render_Mode' => 'Жапсырманы көрсету',
'Label_Render_Mode_Hint' => 'Жапсырманың қалай салынатыны. Принтер қаріптері ең жылдам және ең анық штрихкод береді, бірақ тек негізгі латын таңбаларын принтердің өз қарпімен басады. Алдын ала қарау суреті жапсырма дизайныңызды дәл қайталайды — таңдаған қаріпіңіз, кез келген тіл — арнайы жапсырма бағдарламасы сияқты.',
'Render_Native' => 'Принтер қаріптері (ең жылдам)',
'Render_Raster' => 'Алдын ала қарау суреті (дәл дизайн)',
'Label_Width_Mm' => 'Жапсырма ені (mm)',
'Label_Height_Mm' => 'Жапсырма биіктігі (mm)',
'Label_Size_Hint' => 'Орамдағы бір стикердің физикалық өлшемі. Ол салынған жапсырмаларға дәл сәйкес келуі керек — қате өлшем принтердің саңылауды дұрыс емес жерден іздеуіне әкеледі, сондықтан әр жапсырма орнынан көбірек ығысып басылады.',
'Calibrate_Labels' => 'Жапсырмаларды калибрлеу',
'Calibrate_Labels_Hint' => 'Принтер стикер мен саңылауды өлшеу үшін бірнеше жапсырманы береді. Жаңа орамды салғаннан кейін немесе басып шығару орындары ығысқанда бір рет іске қосыңыз.',
'Calibration_Sent' => 'Калибрлеу басталды — принтер оларды өлшеу үшін бірнеше бос жапсырманы береді. Тоқтағанда тестілік басып шығаруды іске қосыңыз.',
'Label_Printer_Dpi' => 'Басып шығару басының ажыратымдылығы',
'Label_Printer_Dpi_Hint' => 'Жапсырма принтерлерінің көпшілігі 203 dpi. Сенімді емессіз бе? Төмендегі «Ажыратымдылықты анықтау» батырмасын пайдаланыңыз — ол жауапты басып шығарады.',
'Find_Resolution' => 'Ажыратымдылықты анықтау',
'Find_Resolution_Hint' => '203 және 300 деп белгіленген екі жапсырма басылады. Дұрысында стикерде төрт жағынан да шағын біркелкі шеті бар толық тіктөртбұрыш көрінеді; қатесінде жиектер жоқ немесе келесі стикерге шығып кетеді.',
'Dpi_Test_Sent' => '203 және 300 деп белгіленген екі жапсырма басылып жатыр. Дұрысында төрт жағынан да шағын, біркелкі шеті бар толық тіктөртбұрыш көрінеді — «Басып шығару басының ажыратымдылығын» сол санға орнатып, сақтаңыз.',
'Label_Offset_X' => 'Көлденең ығысу (mm)',
'Label_Offset_X_Hint' => 'Стикердегі басып шығаруды жанына жылжытады. Мәтін бір шетінен қиылғанда пайдаланыңыз — мысалы, ақ стикер кеңірек негіз қағаздың ортасында тұрса, 2.5. 0.5 қадаммен реттеңіз.',
'Label_Offset_Y' => 'Тік ығысу (mm)',
'Label_Offset_Y_Hint' => 'Басып шығаруды жапсырма бойымен жылжытады. Дизайнның жоғарғы жағы қиылса немесе жоқ болса, арттырыңыз; тым төменнен басталса, азайтыңыз.',
'Feed_To_Tear' => 'Жыртып алу жиегіне беру',
'Feed_To_Tear_Hint' => 'Әр тапсырмадан кейін жапсырманы жыртып алу жолағына дейін жылжытады. Жапсырмалар төмен ығысып басылса немесе стикерлер арасында бөлінсе, ӨШІРУЛІ қалдырыңыз — көптеген принтерлер келесі жапсырма алдында кері қайтпайды.',
