'Ord_Guide_Payment_Paid' => 'Тұтынушы төлем шлюзі арқылы онлайн төлеп қойған. Тапсырысты растау сатуды Төленген ретінде құрып, төлемді сіз үшін тіркейді — басқа ештеңе жасаудың қажеті жоқ.',
