'Ord_Guide_MarkPaid_Step3' => 'Жол әрекеттері мәзірін ашып, Төлем құру тармағын таңдаңыз.',
'Ord_Guide_MarkPaid_Step4' => 'Соманы, төлем әдісін және күнді енгізіп, сақтаңыз. Сомаға байланысты сату өздігінен Ішінара немесе Төленген күйіне ауысады.',
'Ord_Guide_MarkPaid_Note' => 'Мұнда көрсетілген Төлем күйі тапсырысты рәсімдеу кезіндегі таңдауды тіркеуді жалғастырады және өзгеріссіз қалады. Сату — бухгалтерлік жазба, және ол төлем мен пайда есептеріңізді толтырады. Енгізгеніңізді қарау немесе өңдеу үшін сатудағы Төлемдерді көрсету әрекетін пайдаланыңыз.',
'Ord_Guide_Notes_Title' => 'Білген жөн',
