'VG_Rows_Text' => 'Әр жолда сурет, код, штрихкод, өзіндік құн, баға, көтерме баға және ең төменгі сату бағасы бар. Тауар құру кезінде әр нұсқа үшін әр қоймадағы бастапқы қорды да енгізуге болады. «Толық емес» тегі жолда бір опцияның мәні жоқ екенін білдіреді.',
'VG_List_Title' => 'Жай тізім режимі',
'VG_List_Text' => 'Жол қосу үшін нұсқа атауын теріп, Enter басыңыз (немесе Қосу батырмасын басыңыз), содан кейін оның коды мен бағаларын толтырыңыз. Бұл — классикалық әрекет және бар тауарлар үшін қолжетімді болып қалады.',
'VG_Edit_Title' => 'Кейін өңдеу',
'VG_Edit_1' => 'Мән қосып, «Нұсқаларды жасау» батырмасын басыңыз: тек жетіспейтін комбинациялар қосылады. Бар жолдар өз кодтарын, бағаларын және тарихын сақтайды.',
'VG_Edit_2' => 'Мәнді немесе опцияны алып тастау оны пайдаланатын жолдарды алып тастайды. Бұрын сақталған жолдар тауарды сақтаған кезде растаудан кейін жойылады.',
'VG_Edit_3' => 'Қоры әлі бар нұсқаны алып тастау мүмкін емес. Алдымен оның қорын түзетіңіз немесе тасымалдаңыз.',
'VG_Edit_4' => '«Жай тізімге» ауысу жолдар мен олардың атауларын сақтайды, бірақ опция анықтамаларын алып тастайды.',
'VG_Store_Title' => 'Онлайн дүкенде',
'VG_Store_Text' => 'Тұтынушылар әр опция үшін бір мән таңдайды, мысалы, алдымен Түс, содан кейін Өлшем. Жоқ комбинациялар өшіріледі, ал қорда жоқтары сызылады. Себетке таңдалған нұсқа түседі.',
