'Upd_Guide_Manual_Title' => '5. Қолмен жаңарту (балама әдіс)',
'Upd_Guide_Manual_Text' => 'Қолмен жаңартуды қаласаңыз немесе серверіңізде жүктеушіні пайдалану мүмкін болмаса, осы беттің {tab} қойындысындағы қадамдық нұсқауларды орындаңыз.',
'Upd_Guide_Clear_Cache_First' => 'Кез келген жаңартудан кейін беттер бұзылған немесе бос көрінсе, алдымен браузер кэшін тазалаңыз — себебі әрдайым дерлік осы.',
'Upd_Restore_Backup_Confirm' => 'Бұл сақтық көшірмені қалпына келтіру керек пе? Ағымдағы файлдар мен ағымдағы дерекқор сақтық көшірмемен ауыстырылады. Алдымен ағымдағы дерекқордың қауіпсіздік көшірмесі алынады. (v{version} — {date})',
