'Woo_Guide_Ways_Note' => 'Shopify-дан айырмашылығы, WooCommerce ERP-ге өздігінен ештеңе жібермейді — мұнда webhook қабылдағыш жоқ, сондықтан {in} келетіннің бәрі кесте бойынша келеді. Тек {out} кететін қор ғана бірден жіберіле алады.',
