'Woo_Guide_Wp_App_Password_Note' => 'Медианы басқара алатын WordPress пайдаланушысын пайдаланып, құпиясөзді {path} бөлімінде жасаңыз. Екі өрісті де бос қалдырсаңыз, бәрі бәрібір синхрондалады — тек суреттерді тіркеу өткізіліп жіберіледі.',
