'Woo_Setting_People_Miss' => 'Көпшілік байқамайтын баптау',
'Woo_Guide_Pos_Sale_Not_Reach' => 'POS сатылымы WooCommerce-ке өздігінен {not}. Өшірулі болса, дүкен бұл туралы тек келесі қор синхрондауында біледі — әдепкі бойынша бір сағаттан кейін — және сол аралықта сіз кассада сатып қойған бірлікті сата алады.',
'Woo_Does_Not' => 'жетпейді',
'Woo_Guide_Tick_Instant' => '{settings} қойындысында {option} белгілеңіз. Барлық баптау осы — worker да, cron да қажет емес. Әр сатылым, қайтару, түзету, ауыстыру және қабылданған сатып алу сатылым сақталғаннан кейін бірден тек сол өнімдерді жібереді, ал жиырма жолдық сатылым жиырма емес, бір жіберуге тең. Касса оны ешқашан күтпейді.',
'Woo_Currently' => 'Қазір:',
'Woo_Instant_On_Text' => 'қосулы — қор өзгергенде жіберіледі',
'Woo_Instant_Off_Text' => 'өшірулі — қор тек кесте бойынша',
'Woo_Guide_Instant_Note' => 'Тек WooCommerce-пен байланыстырылған өнімдер жіберіледі — ешқашан синхрондалмаған өнімнің дүкенде түзететін ештеңесі жоқ. Вариативті өнімдер өздерінің негізгі өнімі арқылы өтеді, ал комбо оның кез келген компоненті қозғалғанда қайта жіберіледі. Жаппай операциялар (өнімді жою, қойманы тазалау) қорды оқиға тудырмай жазады, бұл сағаттық қор синхрондауын да сақтаудың бір себебі.',
'Woo_Push_Products_On_Save' => 'Өнімдерді сақталған сәтте жіберу',
'Woo_Guide_Tick_Auto_Products' => '{settings} қойындысында {option} белгілеңіз, сонда Stocky-де жасалған, өңделген немесе көшірілген өнім сақталғаннан кейін бірден WooCommerce-ке жіберіледі — мәліметтері, бағасы, варианттары және суреттері, содан кейін қоры. Жаңа өнім түнгі өнімдер синхрондауын күтпей, дүкенде бірден жасалады.',
'Woo_On' => 'қосулы',
'Woo_Off' => 'өшірулі',
'Woo_Guide_Bulk_Imports_Note' => 'Жаппай импорттар бір-бірлеп жіберілмейді — импорттан кейін өнімдерді синхрондауды іске қосыңыз. Жіберілген өнім дұрыс санатқа түсуі үшін алдымен санаттар мен брендтерді синхрондаңыз.',
'Woo_Nothing_Else_To_Install' => 'Басқа ештеңе орнатудың қажеті жоқ',
'Woo_Guide_Same_Process' => 'Кезек worker-і де, cron жазбасы да жоқ. Жіберу сатылымға қызмет еткен процесте, жауап қайтарылғаннан {after} орындалады, сондықтан касса ешқашан WooCommerce-ті күтпейді. Жіберулер ешқашан қабаттаспайды: біреуі орындалып жатқанда жасалған өзгерістер оны күтіп, бірден кейін жіберіледі.',
'Woo_After' => 'кейін',
'Woo_Guide_Shop_Stops_Answering' => 'Жауап беруді тоқтатқан дүкен сегіз секундтан кейін тасталады, ал әр сатылым оны қайта күтпеуі үшін жіберулер бес минутқа тоқтатылады; осы аралықта түскен өзгерістер үзілістен кейінгі алғашқы жіберумен кетеді, ал сағаттық қор синхрондауы бәрібір қуып жетеді. Әр үзіліс Журналдар қойындысында тіркеледі.',
'Woo_Guide_Artisan_Exception' => 'Бір ерекшелік: artisan командасы жасаған қор өзгерісінің кейін келетін жауабы жоқ, сондықтан ол оның орнына {queue} кезегіне қойылады. Оларды да жедел жіберу үшін сол кезекті өңдеңіз:',
'Woo_Cron_Line_Copied' => 'Cron жолы көшірілді',
'Woo_Command_Copied' => 'Команда көшірілді',
'Woo_Guide_Not_Woo_Queue' => 'Әдейі {queue} кезегі емес: ол сағаттарға созылатын каталог топтамаларын тасымалдайды, ал оның артында кезекке тұрған жедел жіберу жедел болмас еді.',
'Woo_On_A_Schedule' => 'Кесте бойынша',
'Woo_Guide_Scheduled_Lead' => 'Бәрі анда-санда екі бағытта да қайта тексеріледі. Тапсырыстар ERP-ге осылай жетеді, каталог осылай жарияланады және жылдам жол өткізіп алған кез келген нәрсе осылай түзетіледі. Әр тапсырманың өз cron жазбасы бар, сондықтан тек қалағаныңызды іске қосасыз.',
'Woo_Guide_Sync_Drains_Queue' => '{command} жұмыс істеп тұрғанда өз кезегін өңдейді, сондықтан бұл жолдарға бөлек worker қажет емес. Windows жүйесінде {program} бағдарламасы мен сол аргументтерді қолданып, {path} ішінде іске қосылатын Тапсырмалар жоспарлағышын пайдаланыңыз.',
'Woo_Or_No_Cron' => 'Немесе мүлдем cron-сыз',
'Woo_Guide_No_Cron_Text' => 'Мұндағы әр қойынды сұраныс бойынша синхрондайды, ал қолмен синхрондау бет ашық тұрғанда өз топтамаларын өңдейді — сондықтан шағын дүкен ешбір cron жазбасынсыз жұмыс істей алады. Жоғалтатыныңыз — ешкім қарамай тұрғанда болатынның бәрі: тапсырыстар тек біреу түймені басқанда ғана келеді.',
'Woo_Commands_Worth_Knowing' => 'Білуге тұрарлық командалар',
'Woo_Worth_Knowing' => 'Білуге тұрарлық',
'Woo_Guide_Changing_Url_Clears' => 'Дүкен URL мекенжайын немесе API кілттерін өзгерту барлық сәйкестендірулерді тазалайды — өнімдер, санаттар, брендтер және тұтынушылар жаңа дүкенге қайтадан синхрондалады.',
'Woo_Guide_Keep_Skus' => 'Stocky мен WooCommerce арасында SKU-ларды бірізді ұстаңыз: бұл қайталануларды болдырмайды және қайта байланыстыруды қауіпсіз етеді.',
'Woo_Guide_Stock_Total' => 'Woo-ға жарияланатын қор — бір қойманың көрсеткіші емес, {total}.',
'Woo_Total_Across_Warehouses' => 'барлық қоймалар бойынша жиын',
'Woo_Guide_Full_Reference' => 'Толық анықтама — әр ауқым, кезектің қалай жұмыс істейтіні және ақауларды жою тізімі — {file} ішінде.',
'Woo_Way_Covers' => 'Қамтиды',
