'Woo_No_Shop_Connected_Desc' => 'Төмендегінің бәрі бәрібір қолданылады — WooCommerce баптаулары бетінде дүкен URL мекенжайы мен API кілттерін енгізіп, қайта оралыңыз.',
'Woo_Wp_Username' => 'WordPress пайдаланушы аты',
'Woo_Wp_App_Password' => 'WordPress қолданба құпиясөзі',
'Woo_Settings_Instant_Hint' => 'Сатылым, қайтару немесе түзету сақталған сәтте тек сол өнімдердің қорын жібереді, сондықтан дүкен келесі сағаттық қор синхрондауында емес, бірнеше секунд ішінде дұрыс болады. Басқа ештеңе орнатудың қажеті жоқ — жіберу сатылымға жауап берілгеннен кейін орындалады, сондықтан касса WooCommerce-ті ешқашан күтпейді. Толығырақ {guide} қойындысында.',
'Woo_Settings_Instant_Off_Alert' => 'Өшірулі қалдырсаңыз, POS сатылымы WooCommerce-ке тек келесі қор синхрондауында — бір сағатқа дейін кешігіп — жетеді.',
'Woo_Settings_Auto_Products_Hint' => 'Stocky-де жасалған, өңделген немесе көшірілген өнім өнімдер синхрондауын күтпей, сақталғаннан кейін бірден WooCommerce-ке жіберіледі — мәліметтері, бағасы, варианттары, суреттері, содан кейін қоры. Жаппай импорттар жіберілмейді; импорттан кейін өнімдерді синхрондауды іске қосыңыз.',
'Woo_Sync_Tuning' => 'Синхрондауды баптау',
'Woo_Sync_Tuning_Intro' => 'Әдепкі мәндер көптеген дүкендерге сәйкес келеді. Оларды тек синхрондау баяу болса немесе хостингіңізде күту уақыты бітсе ғана өзгертіңіз. Әр мән қауіпсіз ауқыммен шектелген, ал өрісті тазалау оның әдепкі мәнін қалпына келтіреді.',
'Woo_Setting_This_Up' => 'Баптау',
'Woo_Setting_This_Up_Text' => 'API кілттерін алу, WordPress қолданба құпиясөзі не үшін қажет, жоспарланған синхрондауларға арналған cron жазбалары және қорды өзгерген сәтте дүкенге қалай жеткізу керек — мұның бәрі осы сервердің көшіруге дайын cron жолдарымен бірге Нұсқаулық қойындысында. Бір ғана көшірме, сондықтан ол модульдің нақты жұмысынан алшақтамайды.',
