'Jumia_Guide_3' => 'Әр Jumia хабарландыруының {sku} мәні Stocky өнім кодына тең екеніне көз жеткізіңіз — бұл қор жіберу мен тапсырыстарды сәйкестендіру үшін қолданылатын идентификатор.',
