'Shopify_Hook_Msg_Token' => 'Төмендегі «Webhook-терді тіркеу» түймесін басып, қосымшаның API secret key мәнін дүкен баптауларына қолтаңба құпиясы ретінде қойыңыз.',
'Shopify_Hook_Note_Register' => 'Тіркеу Shopify-да жазылымдарды жасайды және оларды автоматты түрде осы мекенжайға бағыттайды. Оны Shopify → Settings → Notifications → Webhooks бөлімінде қолмен қоспаңыз: олар басқа құпиямен қол қойылады және әр жеткізу қабылданбайды.',
