'Shopify_G_Lead_Store' => 'Бұл дүкенге сәйкестікті сақтау үшін не қажет. Мұндағының бәрі осы дүкенге тән — жолдар мен id-лер нақты, сондықтан командаларды тікелей серверге көшіруге болады.',
'Shopify_G_Lead_Generic' => 'Shopify дүкені ERP-мен қалай сәйкестікте болады. Өз күйін көру үшін жоғарыдан дүкенді таңдаңыз немесе осылай оқыңыз — cron жолы мен webhook URL қай дүкенді қоссаңыз да бірдей.',
'Shopify_G_Ways_Note' => 'Көптеген дүкендер екеуін де пайдаланады: біріншісі дүкенді минут сайын өзекті ұстайды, екіншісі біріншісі өткізіп алғанды ұстайды — ешқашан келмеген webhook, Shopify әкімші панелінде тікелей жасалған өзгеріс, сайт істемей тұрған түн.',
'Shopify_G_Both_Need' => 'Екі бағытқа да алдымен мына қажет',
'Shopify_G_Credentials' => 'Shopify тіркелгі деректері',
'Shopify_G_Cred_Intro' => '2026 жылдың қаңтарынан бастап Shopify әкімші панелінде custom app жасамайды, сондықтан қосылымның екі түрі бар:',
'Shopify_G_Cred_DevDash' => '{app} (қазір қосылған кез келген дүкен) — {path}. Бұл дүкен синхрондайтын деректерге Admin API рұқсат аумақтарын беріп, қосымшаны дүкенге орнатыңыз, содан кейін {clientId} мен {clientSecret} мәндерін қосымшаның Settings бетінен {where} ішіне көшіріңіз. ERP оларды кіру токеніне өзі айырбастайды және оның мерзімі бітпес бұрын әр 24 сағат сайын жаңартады. Client secret webhook-терге де қол қояды, сондықтан басқа ештеңе қажет емес. Қосымша мен дүкен бір Shopify ұйымында болуы керек.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard қосымшасы',
'Shopify_G_Cred_Legacy' => '{app} (2026 жылға дейін әкімші панелінде жасалған) — өзінің {token} ({prefix}) және webhook қолтаңба құпиясы ретінде {secret} арқылы өзгеріссіз жұмыс істей береді. Бұл токенмен бірдей мән емес, ал оларды шатастыру — webhook-тердің қабылданбауының әдеттегі себебі.',
'Shopify_G_Legacy_App' => 'Ескі custom app',
