'Shopify_G_Stored' => 'сақталған',
'Shopify_G_Missing_Refused' => 'жоқ — жеткізулер қабылданбайды',
'Shopify_G_Where_Data_Desc' => '{path} Осы дүкен қорын сататын ERP қоймасы және сол қор жазылатын Shopify орны. Қорды синхрондау да, тапсырыстарды импорттау да оларсыз іске қосылмайды.',
'Shopify_G_Currently' => 'Қазір: қойма {warehouse}, орын {location}',
'Shopify_G_Not_Set_Lower' => 'орнатылмаған',
'Shopify_G_Ready' => 'дайын',
'Shopify_G_Incomplete' => 'толық емес',
'Shopify_G_Manual_Syncs' => 'Қолмен басталатын синхрондаулар',
'Shopify_G_Manual_Desc' => '{centre} ішінен басталған синхрондау бірден жауап береді және фонда қысқа бөліктермен орындалады, әрқайсысы алдыңғысы тоқтаған жерден жалғасады. Ұзақ веб-сұраныстарды тоқтататын хостинг (LiteSpeed, nginx, жүктеме теңестіргіш) үлкен каталогты ешқашан жартылай үзбейді, ал бетті жабу оны тоқтатпайды. Ол үшін worker — тағы бір cron жолы:',
'Shopify_G_Cron_Copied' => 'Cron жолы көшірілді',
'Shopify_G_Manual_Note' => 'Онсыз да синхрондау аяқталады, бірақ тек Синхрондау орталығы беті ашық тұрғанда: бірнеше секунд ішінде ешбір worker іске қосуды алмаса, бет оны бір-бір қысқа сұраныспен өзі жалғастырады. Windows жүйесінде Тапсырмалар жоспарлағышын әр минут сайын пайдаланыңыз: бағдарлама {program}, аргументтер {args}, {dir} ішінде іске қосылады.',
'Shopify_G_Then_Pick' => 'Содан кейін сәйкестікті қалай сақтайтынын таңдаңыз',
'Shopify_G_Right_Away' => 'Бірден',
'Shopify_G_Stock_Live' => 'қор нақты уақытта',
'Shopify_G_Stock_Not_Live' => 'қор нақты уақытта емес',
'Shopify_G_Realtime_Lead' => 'Әр өзгеріс болған сәтте, бірнеше секунд ішінде жіберіледі. Екі бөлік бар және олар бөлек қосқыштар: {webhooks} дүкеннің өз оқиғаларын ішке әкеледі, ал {push} қорды сыртқа жібереді.',
'Shopify_G_Webhooks_Lower' => 'webhook-тер',
'Shopify_G_Instant_Push_Lower' => 'жедел қор жіберу',
'Shopify_G_Webhooks_In' => 'Webhook-тер — дүкен → ERP',
'Shopify_G_Webhooks_Desc' => 'Тапсырыстар, тапсырыс күйінің өзгерістері және Shopify-да жасалған өнім, тұтынушы және қор өзгерістері. Дүкенді ашып, оның {tab} бөлімінде {button} басыңыз — екі рет басу қауіпсіз. Shopify мына мекенжайға жібереді:',
'Shopify_G_Webhooks_Tab' => 'Webhooks қойындысы',
'Shopify_G_Webhooks_Note' => 'Мекенжай интернеттен HTTPS арқылы қолжетімді болуы керек — Shopify {localhost} немесе {test} доменіне жеткізбейді. Әр жеткізу бір рет тіркеледі, сондықтан Shopify қайталаулары қайталанған тапсырыс жасай алмайды, ал сәтсізін қайта ойнатуға болады. 1-қадамдағы қолтаңба құпиясы сақталмайынша жеткізулер қабылданбайды.',
'Shopify_G_Instant_Out' => 'Жедел қор жіберу — ERP → дүкен',
'Shopify_G_Setting_Missed' => 'Көпшілік байқамайтын баптау',
'Shopify_G_Pos_Not_Auto' => 'POS сатылымының Shopify-ға өздігінен жетуі мүмкін {not}. Өшірулі болса, дүкен бұл туралы тек келесі Қорды жіберу қадамында біледі — және сол аралықта ол сіз кассада сатып қойған бірлікті сата алады.',
'Shopify_G_Not' => 'емес',
'Shopify_G_Tick_Push' => '{where} ішінде {setting} белгілеңіз. Барлық баптау осы — worker да, cron да қажет емес. Әр сатылым, қайтару және түзету сатылым сақталғаннан кейін бірден тек сол өнімдерді жібереді, ал жиырма жолдық сатылым жиырма емес, бір жіберуге тең. Касса оны ешқашан күтпейді.',
'Shopify_G_This_Store' => 'Бұл дүкен:',
'Shopify_G_Push_On' => 'қосулы — қор өзгергенде жіберіледі',
'Shopify_G_Push_Off' => 'өшірулі — қор тек кесте бойынша',
'Shopify_G_Push_Note' => 'Тек Shopify сәйкестендіруі бар өнімдер және тек осы дүкен қоймасындағы қозғалыстар жіберіледі. Жаппай операциялар — өнімді жою, қойманы тазалау — қорды оқиға тудырмай жазады, бұл жоспарланған қор қадамын да сақтаудың бір себебі.',
'Shopify_G_Nothing_Install' => 'Басқа ештеңе орнатудың қажеті жоқ',
'Shopify_G_No_Worker_Note' => 'Екі бөлікке де кезек worker-і немесе cron жазбасы қажет емес. Келген webhook Shopify жасаған сұраныста өңделеді; шығатын қор жіберу сатылымға қызмет еткен процесте, жауап қайтарылғаннан {after} орындалады — сондықтан касса Shopify-ды ешқашан күтпейді, ал жауап беруді тоқтатқан дүкен он секундтан кейін тасталып, келесі жоспарланған қор жіберуіне қалдырылады.',
'Shopify_G_After' => 'кейін',
'Shopify_G_Artisan_Note' => 'Бір ерекшелік: artisan командасы жасаған қор өзгерісінің кейін келетін жауабы жоқ, сондықтан ол оның орнына {queue} кезегіне қойылады. Оларды да жедел жіберу қажет болса, сол кезекті өңдеңіз:',
'Shopify_G_On_Schedule' => 'Кесте бойынша',
'Shopify_G_On_Lower' => 'қосулы',
'Shopify_G_Off_Lower' => 'өшірулі',
'Shopify_G_Scheduled_Lead' => 'Бәрі анда-санда екі бағытта да қайта тексеріледі. Нақты уақыттан баяу, бірақ жедел жіберуді пайдаланбайтын дүкендерде қорды осы жібереді, өткізіп алынған webhook-ті осы ұстайды және бүкіл каталогты тасымалдаудың жалғыз жолы осы.',
'Shopify_G_Cron_Entry' => 'Cron жазбасы',
'Shopify_G_Cron_Entry_Desc' => 'Онсыз жоспарланған ештеңе орындалмайды. Бір жол, тек осы модуль үшін — оны жоспарлауға таңдаған басқа жазбаларыңыздың жанына қосыңыз:',
'Shopify_G_Cron_Note' => 'Әр бес минут — жоспар қолдана алатын ең жоғары дәлдік, себебі бес минут — ең қысқа қадам интервалы. Ірірек жазба жай ғана төменгі шекке айналады — {example} болса, 5 минутқа орнатылған қадам әр 15 минут сайын орындалады. Windows жүйесінде Тапсырмалар жоспарлағышын пайдаланыңыз: бағдарлама {program}, аргументтер {args}, {dir} ішінде іске қосылады.',
'Shopify_G_Switch_On_Plan' => 'Оны қосып, жоспарды таңдаңыз',
'Shopify_G_Plan_Desc' => '{where} Қосқыш cron-ның әрекет ете алатынын анықтайды; жоспар оның не істейтінін анықтайды. {step} — өз интервалы бар бір бағыттағы бір нысан — {first}, {second}. Әдепкі интервалды өз өрісін бос қалдырған кез келген қадам пайдаланады.',
'Shopify_G_Step_Lower' => 'қадам',
