'Cr_Guide_Step_Webhook' => 'Webhook URL тіркеңіз',
'Cr_Guide_Step_Webhook_Help' => 'Жаңартуларды өздері жіберетін курьерлерге мәртебелер бірден өзгеруі үшін аккаунттың webhook URL-і (төменде көрсетілген) қажет. Қалғандары кесте бойынша тексеріледі.',
