'Cr_Guide_T_Statuses' => 'Мәртебелер',
'Cr_Guide_Statuses_Note' => 'Мәртебелер тек алға жылжиды, сондықтан кешіккен жаңарту сәлемдемені ешқашан артқа қайтармайды. Жеткізілген сәлемдеме бәрібір қайтарылуда немесе қайтарылды деп хабарлануы мүмкін.',
'Cr_Guide_S_booked' => 'Тапсырыс курьерде; оны әлі ешкім алып кетпеген. Брондауды тек осы кезде болдырмауға болады.',
