'Cr_Guide_S_delivered' => 'Тұтынушыға тапсырылды. COD сомасы курьер алды күйіне өтеді.',
'Cr_Guide_S_returning' => 'Сізге қайтару жолында.',
'Cr_Guide_S_returned' => 'Сізге қайтарылды: Тексерілетін қайтаруларда күтеді немесе қорға автоматты түрде қайтарылады.',
'Cr_Guide_S_cancelled' => 'Брондау болдырылмады.',
'Cr_Guide_T_Booking' => 'Тапсырыстарды брондау',
'Cr_Guide_B_Booking' => 'Курьерге жіберу пішінді сату деректерімен толтырады: алушы, мекенжай, COD ретінде әлі төленуге тиіс сома және тауарлардың салмағы. Өз қалалар тізімі бар курьерлер таңдау тізімін көрсетеді, ал сіздің таңдауыңыз сол қала үшін есте сақталады. Агрегаторлар, DHL, FedEx, UPS және Lalamove Тарифтерді салыстыру мүмкіндігін ұсынады: бағаны таңдаңыз, ал Брондау оны сатып алады. Сатулар тізімінен бірнеше сатуды бірден брондауға болады.',
'Cr_Guide_T_Cod' => 'Жеткізу кезінде төлеу',
'Cr_Guide_B_Cod' => 'COD сәлемдемесі Алынбаған күйінен Курьер алды (жеткізу кезінде) күйіне, одан Сізге аударылды күйіне өтеді. Аударымдар туралы хабарлайтын курьерлер соңғы қадамды өздері жылжытады; қалғандары үшін COD жаңарту батырмасын пайдаланыңыз. Курьер баптауларында шот таңдалған болса, аударым сатудағы төлем ретінде тіркеледі. Сәлемдеме аяқталғаннан кейін курьер төлемақыларын шығыс ретінде сақтауға болады.',
'Cr_Guide_T_Returns' => 'Қайтарылған сәлемдемелер',
'Cr_Guide_B_Returns' => 'Әдепкі бойынша қайтарылған сәлемдеме Курьерлік жөнелтімдердегі Тексерілетін қайтарулар бөлімінде күтеді. Қорға қайтару бүкіл тапсырыс бойынша сатуды қайтаруды жасап, тауарларды қорға қайтарады; Қабылдамау зақымдалған немесе жоғалған сәлемдемелер үшін ештеңе қайтармайды. Оның орнына Курьер баптаулары қорға автоматты түрде қайтаруы мүмкін.',
'Cr_Guide_T_Customers' => 'Тұтынушы хабарламалары және бақылау беті',
'Cr_Guide_B_Customers' => 'Курьер баптауларындағы тұтынушы хабарландырулары сіз белгілеген мәртебелерде SMS, email немесе WhatsApp жібереді, әр сәлемдемеге бір реттен, өз мәтініңізбен. Онлайн дүкеніңіздегі бақылау беті тұтынушыларға сәлемдемені бақылау нөмірі немесе тапсырыс нөмірі мен телефоны бойынша бақылауға мүмкіндік береді. Сәлемдемелерді жиі қайтаратын тұтынушылар брондау кезінде қайтару тәуекелі белгісін алады.',
'Cr_Guide_T_Labels' => 'Жапсырмалар',
'Cr_Guide_B_Labels' => 'Жапсырманы басып шығару курьер жапсырма берсе, соның өзін береді (PDF, сілтеме немесе сурет), әйтпесе бақылау штрихкоды мен алынатын сомасы бар Stocky жапсырмасын береді. Басып шығару үшін осы сайтқа қалқымалы терезелерге рұқсат беріңіз. DHL, FedEx және UPS өз жапсырмасын тек бір рет, брондау кезінде береді, ал Stocky оны қайта басып шығару үшін сақтайды.',
'Cr_Guide_T_Faq' => 'Ақауларды жою',
'Cr_Guide_Q_Test' => 'Қосылымды тексеру сәтсіз аяқталады',
'Cr_Guide_A_Test' => 'Сынақ кілттері Сынақ режимімен, ал нақты кілттер Нақты режиммен пайдаланылады; олар әртүрлі. Нақты себебін білу үшін Курьер журналдарын ашып, курьердің жауабын оқыңыз.',
'Cr_Guide_Q_City' => 'Курьер қаланы немесе мекенжайды қабылдамайды',
'Cr_Guide_A_City' => 'Брондау пішініндегі курьер қалалары тізімінен қаланы таңдаңыз; курьерлер тек өз атауларын қабылдайды. Пошта мекенжайларымен жұмыс істейтін курьерлерге штат, пошта индексі және екі әріпті ел коды да қажет.',
'Cr_Guide_Q_Webhook' => 'Мәртебелер өздігінен өзгермейді',
'Cr_Guide_A_Webhook' => 'Жаңартуларды өздері жіберетін курьерлер үшін webhook URL курьерде тіркелгенін тексеріңіз: Курьер журналдары алынған әр жаңартуды немесе оның неге қабылданбағанын көрсетеді (мысалы, қате құпия кілт). Басқа курьерлер Курьер баптауларындағы кесте бойынша тексеріледі, ал Мәртебені қазір тексеру бірден сұрау жібереді.',
'Cr_Guide_Q_Stuck' => 'Жөнелтімде мәртебені тексеру қатесі көрсетіледі',
'Cr_Guide_A_Stuck' => 'Курьер соңғы тексерулерден бас тартты; себебі жөнелтімде және Курьер журналдарында көрсетілген. Қайталанған сәтсіздіктерден кейін жөнелтім автоматты түрде тексерілмейді: себебін жойып, содан кейін Мәртебені қазір тексеру батырмасын пайдаланыңыз.',
