'Tfa_Guide_Codes_Text' => 'Баптаудан кейін бірден 8 қалпына келтіру коды бір рет көрсетіледі. Әрқайсысы телефон кодын бір рет алмастырады — телефон жоғалса, бұзылса немесе қалпына келтірілсе. Оларды жүктеп алыңыз немесе көшіріп, телефоннан бөлек қауіпсіз жерде сақтаңыз.',
'Tfa_Guide_Codes_Note' => 'Кодтар азайып қалды ма? Профильдегі «Жаңа қалпына келтіру кодтары» бүкіл жиынтықты алмастырады; ескілері жұмыс істемей қалады.',
'Tfa_Guide_Signin_Title' => 'Кіру',
'Tfa_Guide_Signin_Text' => 'Email мен құпиясөзден кейін кіру беті қолданбадағы ағымдағы кодты сұрайды. Кодтар әр 30 секунд сайын өзгереді және әрқайсысы бір рет жұмыс істейді.',
'Tfa_Guide_Signin_Trust' => '«Осы құрылғыда қайта сұрамау» белгісін қойса, сол браузерде :days күн бойы код сұралмайды.',
'Tfa_Guide_Signin_Recovery' => 'Телефон қолыңызда жоқ па? «Қалпына келтіру кодын пайдалану» түймесін басып, сақталған кодтардың бірін теріңіз.',
'Tfa_Guide_Admin_Title' => 'Әкімшілер үшін',
'Tfa_Guide_Require_Title' => 'Оны міндетті ету',
'Tfa_Guide_Require_Text' => 'Осы картадағы «Екі факторлы аутентификацияны талап ету» опциясын қосыңыз, содан кейін оны пайдалануы тиіс рөлдерді таңдаңыз — немесе барлық пайдаланушы үшін тізімді бос қалдырыңыз. Сақтау үшін «Жіберу» түймесін басыңыз.',
'Tfa_Guide_Require_Next' => 'Ешкім жүйеден шығарылмайды. 2FA әлі жоқ пайдаланушыларға келесі кіру кезінде, кірмес бұрын кіру бетінде баптау қадамдары көрсетіледі және сол жерде қалпына келтіру кодтары беріледі.',
'Tfa_Guide_Require_Note' => 'Ол міндетті болған пайдаланушылар оны профилінен өшіре алмайды.',
'Tfa_Guide_Trust_Title' => 'Сенімді құрылғылар',
'Tfa_Guide_Trust_Text' => '«Сенімді құрылғыларды есте сақтау» сәтті кіруден кейін браузер кодты қанша уақыт өткізіп жібере алатынын анықтайды. Ортақ немесе қоғамдық компьютерлер үшін, мысалы, сауда залындағы POS үшін «Әрдайым код сұрау» опциясын таңдаңыз.',
'Tfa_Guide_Trust_Note' => 'Санды азайту бұрыннан сенімді құрылғылардың мерзімін қысқартады; 2FA өшіру немесе қалпына келтіру олардың барлығын ұмыттырады.',
'Tfa_Guide_Lost_Title' => 'Телефон жоғалды және қалпына келтіру кодтары жоқ',
'Tfa_Guide_Lost_Text' => 'Пайдаланушылар бетінде 2FA қосқан пайдаланушылардың 2FA бағанында «Қосулы» көрсетіледі. Әрекеттер бөліміндегі қалқан түймесі оны қалпына келтіреді: пайдаланушы тек құпиясөзбен кіріп, қолданбаны қайта баптайды (немесе міндетті болса, баптау сұралады).',
'Tfa_Guide_Lost_Warn' => 'Қалпына келтірмес бұрын кім сұрап тұрғанын растаңыз — қалпына келтіру сол аккаунттың 2FA қорғанысын алып тастайды.',
'Tfa_Guide_Open_Users' => 'Пайдаланушыларды ашу',
'Tfa_Guide_Mobile_Title' => 'Мобильді қолданба және API',
'Tfa_Guide_Mobile_Text' => 'Мобильді қолданба мен API токен нүктесі де дәл сол кодты сұрайды. Егер 2FA әлі баптамаған пайдаланушы үшін міндетті болса, ол мұны істеу үшін вебке бір рет кіруі тиіс.',
'Tfa_Guide_Protect_Title' => 'Кіріктірілген қорғаныс',
'Tfa_Guide_Protect_1' => '5 қате код жоғарыдағы бұғаттау баптауларына қарамастан сол пайдаланушы үшін код енгізуді 15 минутқа бұғаттайды.',
'Tfa_Guide_Protect_2' => 'Әр код және әр қалпына келтіру коды тек бір рет жұмыс істейді.',
'Tfa_Guide_Protect_3' => '«Кіру әрекеттерін тіркеу» қосулы болса, қате кодтар Кіру әрекеттері тізімінде «Қате 2FA коды» ретінде көрсетіледі.',
'Tfa_Guide_Trouble_Title' => 'Ақауларды жою',
'Tfa_Guide_Faq_Clock_Q' => 'Жаңа кодпен «Бұл код жарамсыз» хабары шығады',
'Tfa_Guide_Faq_Clock_A' => 'Телефон сағаты дұрыс емес болуы мүмкін. Кодтар уақытқа байланысты: телефонның күні мен уақытын автоматты (желі уақыты) етіп орнатыңыз, содан кейін келесі кодты көріңіз.',
'Tfa_Guide_Faq_Phone_Q' => 'Жаңа телефонға көшу',
'Tfa_Guide_Faq_Phone_A' => 'Аутентификатор қолданбасының өз тасымалдау функциясын пайдаланыңыз немесе профильде 2FA өшіріп, жаңа телефонмен қайта қосыңыз (егер міндетті болса, оның орнына әкімшіден оны қалпына келтіруді сұраңыз).',
'Tfa_Guide_Faq_Locked_Q' => '«Жарамсыз кодтар тым көп»',
'Tfa_Guide_Faq_Locked_A' => 'Көрсетілген уақытты күтіңіз (15 минутқа дейін) немесе әкімшіден пайдаланушының 2FA-сын қалпына келтіруді сұраңыз.',
'Tfa_Guide_Faq_Key_Q' => 'Серверді көшіргеннен кейін 2FA қосқан ешкім кіре алмайды',
'Tfa_Guide_Faq_Key_A' => '2FA құпиялары .env файлындағы APP_KEY арқылы шифрланған. Қолданбаны көшіргенде немесе қалпына келтіргенде сол APP_KEY сақтаңыз; егер ол өзгерсе, 2FA жоқ әкімші зардап шеккен пайдаланушыларды қалпына келтіруі тиіс.',
'Tfa_Guide_Button' => 'Нұсқаулық',
'Tfa_Guide_Title' => 'Екі факторлы аутентификация нұсқаулығы',
