'Sec_2fa_Applied' => ':count пайдаланушы жүйеден шығарылды.',
'Tfa_Guide_Rollout_Title' => 'Оны барлық пайдаланушыға енгізу',
'Tfa_Guide_Rollout_1' => 'Қадамдарды білу үшін алдымен оны өз аккаунтыңызға қосыңыз (Профиль).',
'Tfa_Guide_Rollout_2' => 'Командаңызға қай қолданбаны орнату керектігін және баптау кіру кезінде бір минут алатынын айтыңыз.',
'Tfa_Guide_Rollout_3' => '«Екі факторлы аутентификацияны талап ету» опциясын қосыңыз, «Кімдерге міндетті» өрісін бос қалдырыңыз (= барлық пайдаланушы) және қаласаңыз жеңілдік кезеңін таңдаңыз. «Жіберу» түймесін басыңыз.',
'Tfa_Guide_Rollout_4' => 'Жүйеге кіріп тұрған адамдар оны кейінгі кіру кезінде емес, қазір баптауы үшін «2FA жоқ пайдаланушыларды шығару» түймесін басыңыз. Сіз жүйеде қаласыз.',
'Tfa_Guide_Rollout_5' => 'Барысын осы картадағы есептегіш немесе Пайдаланушылар бетіндегі «Баптау қажет» сүзгісі арқылы бақылаңыз.',
'Tfa_Guide_Rollout_Note' => 'Жеңілдік кезеңі болса, баптау бетінде мерзім аяқталғанша «Кейінірек еске салу» көрсетіледі; одан кейін кіру үшін баптау міндетті.',
'Tfa_Guide_Customers_Title' => 'Тұтынушы аккаунттары (дүкен және клиент порталы)',
'Tfa_Guide_Customers_Text' => 'Тұтынушылар да өз аккаунттарын қорғай алады. Бұл әр тұтынушы үшін міндетті емес және ешқашан мәжбүрленбейді: оны Дүкен баптаулары → Тіркелуге қол жеткізуді басқару (онлайн дүкен) және Клиент порталы → Портал баптаулары (клиент порталы) бөлімдерінде қосыңыз.',
'Tfa_Guide_Customers_1' => 'Тұтынушылар оны Менің аккаунтым (дүкен) немесе Профиль (портал) бөлімінен қосады.',
'Tfa_Guide_Customers_2' => 'Олар email арқылы жіберілетін кодты — ең оңайы, қолданба қажет емес — немесе қалпына келтіру кодтары бар аутентификатор қолданбасын таңдайды.',
'Tfa_Guide_Customers_3' => 'Email арқылы жіберілетін кодтар үшін пошта баптаулары жұмыс істеуі керек (Баптаулар → Пошта баптаулары). Олардың мерзімі 10 минуттан кейін өтеді.',
'Tfa_Guide_Customers_4' => 'Кейін опцияны өшіру жаңа баптауларды тоқтатады; оны пайдаланып жүрген тұтынушылардан код сұрала береді және олар оны өздері өшіре алады.',
'Tfa_Required_Grace_Notice' => 'Әкімшіңіз екі факторлы аутентификацияны талап етеді. Кіру кезінде оны :date дейін кейінге қалдыра аласыз; одан кейін баптау міндетті.',
